 function openCompanion(j:any){bridgeCleanup.current?.();const nonce=crypto.randomUUID();let request:any=null,received=false,started=false;const popup=window.open(companionOrigin+'/#bridge='+encodeURIComponent(nonce),'_blank','popup,width=900,height=850');if(!popup){setError('Allow this popup to open the companion.');return;}const listener=async(event:MessageEvent)=>{if(!acceptsCompanionMessage(event,popup,nonce))return;if(event.data.type==='omnidev-ready'&&!started){started=true;try{const r=await fetch('/api/runtime?action='+(j.reviewIndex!==undefined?'accountReviewRequest':'accountRequest')+'&id='+encodeURIComponent(j.parentJobId||j.id)+(j.reviewIndex!==undefined?'&index='+j.reviewIndex:''));request=await r.json();if(!r.ok)throw new Error(request.error||'Cannot load account request');popup.postMessage({type:'omnidev-request',nonce,request},companionOrigin);setError('');}catch(e:any){setError(e.message);}}if(event.data.type==='omnidev-candidate'&&request&&!received){const candidate=event.data.candidate;if(candidate?.jobId!==j.id||candidate?.sourceDigest!==request.sourceDigest){setError('Companion output does not match this job.');return;}received=true;try{const staged=await act({action:j.reviewIndex!==undefined?'submitAccountReview':'submitAccountCandidate',id:j.parentJobId||j.id,index:j.reviewIndex,candidate});popup.postMessage({type:'omnidev-accepted',nonce},companionOrigin);toast.success('Companion candidate returned and staged for review');onUpdate();}catch{popup.postMessage({type:'omnidev-rejected',nonce},companionOrigin);}finally{bridgeCleanup.current?.();}}};window.addEventListener('message',listener);const timer=setTimeout(()=>{if(!started)setError('Start OPEN-COMPANION.cmd on this computer, then click Open companion again.');},10000);const expire=setTimeout(()=>bridgeCleanup.current?.(),600000);bridgeCleanup.current=()=>{window.removeEventListener('message',listener);clearTimeout(timer);clearTimeout(expire);bridgeCleanup.current=null;};}
