 const execute=async()=>{try{if(autoReview&&project?.data.origin?.url)await scanRepository();const j=await act({action:'enqueue',idempotencyKey:crypto.randomUUID(),mode,projectId:project?.id,objective:objective.trim()||(healing?'Repair missing documentation and snapshot tests; preserve a rollback baseline.':''),automaticRepair:autoRepair,automaticReview:autoReview,reviewBudget,runControl:{mode:reviewMode,callLimit:reviewBudget,minutes:reviewMinutes},recommendSpecialists,testProfile:testProfile==='auto'?(applicationReady?'node-application':'snapshot'):testProfile,specialistId,kind:healing?'heal':'development'});let current=j;for(let attempt=0;current.status==='queued'&&j.mode!=='account'&&attempt<3;attempt++)current=await act({action:'tick',id:j.id});if(j.mode==='account'){await connectInsideOmni(j,true);}toast.success(j.mode==='account'?'Job ready: generate with your account brain':'Candidate generated and checked');onUpdate()}catch{}};
