 const detail=selected?state.jobs.find((j:any)=>j.id===selected.id)||selected:null;const gapGroups=groupCapabilityGaps(state.capabilityGaps||[]);const visibleJobs=shown.filter((j:any)=>(jobFilter==='all'||(jobFilter==='active'?jobPresentation(j,engineBoards[j.id]).active:['queued','awaiting review'].includes(j.status)))&&(!jobSearch||(j.objective+' '+j.id+' '+j.payload.projectTitle).toLowerCase().includes(jobSearch.toLowerCase())));visibleJobs.sort((a:any,b:any)=>Number(!!a.payload.pipelineParentId)-Number(!!b.payload.pipelineParentId));const activeJobs=state.jobs.filter((j:any)=>jobPresentation(j,engineBoards[j.id]).active);
